43	        if (membersError) {
44	            console.error('Error fetching members:', membersError);
45	            return { data: [], error: membersError };
46	        }
47	
48	        // attendance.usersからカード情報を取得
49	        const { data: attendanceUsers } = await supabase
50	            .schema('attendance')
51	            .from('users')
52	            .select('supabase_auth_user_id, card_id');
53	
54	        const cardMap = new Map(attendanceUsers?.map(u => [u.supabase_auth_user_id, u.card_id]) || []);
55	
56	        // 最新の打刻情報を取得
57	        const memberIds = members?.map((m: any) => m.supabase_auth_user_id) || [];
